  (* [comment removed for export] *)
  Lemma INV0_after_heap : forall own own' st st' LX SP' m m' (errv' : word),
    INV0 own st m ->
    rheap_pres LX SP' m m' -> SP' <= usp + -80 -> (forall b, In b LB -> In b LX) ->
    bytes_at psegs m' (dptr own') (zbytes payload) -> ps_so st' = ps_so st ->
    rw_cells psegs m' RERRNO [C4 errv'] -> mem_inv psegs m' -> stk psegs m' lo (usp + -80) -> rauxv_ok m' AB ->
    INV0 own' st' m'.
