  (* [comment removed for export] *)
  Lemma calls_loop : forall (n : nat) own rc st ms,
    (1 <= n <= 4)%nat -> match own with None => plen = 0 | Some _ => True end ->
    RUNST own 0x130b8 (Z.of_nat n) st ms ->
    implM psegs (run_calls Prog.fuzz_one (io_emit Prog.io) n payload rc) st (fun rc' st' ms' => RUNST own 0x130f0 0 st' ms' /\ rc' = 0) ms.
